import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-124: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short124', durationInSeconds: 35.0, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short124: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(32.3);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'FREE SANDBOX' }, { text: '1,550 HOURS', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(4.3)}>
        <CoverImage src="projects/short-124/cover.png" out={secToFrame(4.3) - 10} />
        <HookTitle hold onDark kicker="CLAUDE API" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(12.6)}>
        <ToolCard name="With search or fetch" tagline="Code execution is free." chip="$0" at={secToFrame(4.3) - 2}>
          <Panel>
            <Line k="web search / fetch" v="in request" />
            <Line k="code execution" v="$0 extra" good />
            <Line k="you pay" v="tokens only" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(17.0)}>
        <ToolCard name="Without those tools" tagline="Billed by time." chip="BILLED" at={secToFrame(12.6) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="billed by" v="execution time" />
            <Line k="minimum" v="5 minutes" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(22.4)}>
        <ToolCard name="Free hours" tagline="Every organization." chip="1,550" at={secToFrame(17.0) - 2}>
          <Panel>
            <Line k="per month" v="1,550 hours" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(26.0)}>
        <ToolCard name="After that" tagline="Per container." chip="$0.05 / hr" at={secToFrame(22.4) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="per hour" v="$0.05" />
            <Line k="per" v="container" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="The trap" tagline="Files preload the box." chip="FILES" at={secToFrame(26.0) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="files attached" v="clock runs" bad />
            <Line k="tool called?" v="not needed" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-124/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="CLAUDE API" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Free with search. Cheap without.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short124;
